import{useEffect,useMemo,useState}from'react';import{EditProject,ScopeManager}from'./Managers';import DeliveredProjects from'./DeliveredProjects';import DeliveredSummary from'./DeliveredSummary';import ApprovalManager from'./ApprovalManager';import{FilesManager,ArchiveManager}from'./WorkspaceTools';import SettingsPage from'./AccountSettings';import{loadWorkspace,saveClients,saveProjects,supabaseConfigured}from'./dataStore';import'./workflow-drag.css';import'./briefing-document.css';import'./access-gate.css';
import{LayoutDashboard,FolderKanban,MessageSquareMore,RefreshCw,CheckCircle2,Users,Files,Settings,Bell,Search,Plus,ArrowUpRight,Clock3,AlertTriangle,ChevronRight,Upload,MoreHorizontal,Eye,CalendarDays,PanelLeftClose,ZoomIn,ZoomOut,Maximize2,Download,Send,Reply,Check,Cloud,FolderOpen,Link2,Activity,PackageCheck,X,MousePointer2,GitCompare,FileImage,Archive,Filter,ChevronDown,Columns3,List,ReceiptText,Copy,ExternalLink,CircleDollarSign}from'lucide-react';

