const initialClients:Client[]=[
 {id:1,name:'Agência 41',type:'Agência parceira',contact:'Equipe 41',email:'contato@agencia41.com.br',projects:4,color:'#d94b23'},
 {id:2,name:'Liga Telecom',type:'Cliente final',contact:'Marketing Liga',email:'marketing@ligatelecom.com.br',projects:2,via:'Agência 41',color:'#3867a8'},
 {id:3,name:'Adega Brasil',type:'Cliente final',contact:'Equipe Adega Brasil',email:'marketing@adegabrasil.com.br',projects:1,via:'Agência 41',color:'#8b603d'}
];
